package main

import "fmt"

// 按业务能力拆分：每个函数像一个独立服务，只管自己的数据。
func userService(id int) string {
	return map[int]string{7: "张三", 8: "李四"}[id]
}

func stockService(sku string, qty int) int {
	return map[string]int{"A-1": 3, "B-2": 0}[sku] - qty
}

// orderService 只做编排：用户、库存都不是它的数据，只能问对应服务。
func orderService(id int, sku string, qty int) string {
	user := userService(id)
	if user == "" {
		return "用户无效"
	}
	if left := stockService(sku, qty); left < 0 {
		return "库存不足"
	}
	return fmt.Sprintf("%s 下单 %s x%d 成功", user, sku, qty)
}

func main() {
	fmt.Println(orderService(7, "A-1", 2))
	fmt.Println(orderService(7, "B-2", 1))
	fmt.Println(orderService(9, "A-1", 1))
}

