package main

import "fmt"

// 单体写法：用户、库存、订单逻辑全挤在 main 里，只覆盖了顺利路径。
func main() {
	users := map[int]string{7: "张三", 8: "李四"}
	stocks := map[string]int{"A-1": 3, "B-2": 0}
	user := users[7]
	if user == "" {
		fmt.Println("用户无效")
		return
	}
	if stocks["A-1"]-2 >= 0 {
		fmt.Println(user, "下单 A-1 x2 成功")
	}
	fmt.Println("库存不足") // 第二笔写死，没有真的走库存判断
	fmt.Println(users[9], "下单 A-1 x1 成功") // 用户 9 不存在却打印成功
}

