package main

import (
	"fmt"
	"strings"
)

// registry 模拟注册中心：服务名 → 实例地址列表，实例会动态上下线。
type registry struct {
	services map[string][]string
}

// register 追加一个实例地址；同一个服务可以有多个副本。
func (r *registry) register(name, addr string) {
	r.services[name] = append(r.services[name], addr)
}

// discover 按服务名查可用实例，调用方不再硬编码地址。
func (r *registry) discover(name string) string {
	instances := r.services[name]
	if len(instances) == 0 {
		return "未找到 " + name + " 的实例"
	}
	return name + " 可用实例: " + strings.Join(instances, ",")
}

func main() {
	r := &registry{services: map[string][]string{}}
	r.register("order", "10.0.0.1:8080")
	r.register("order", "10.0.0.2:8080")
	r.register("user", "10.0.0.3:8080")
	fmt.Println(r.discover("order"))
	fmt.Println(r.discover("user"))
	fmt.Println(r.discover("pay"))
}

