package main

import "fmt"

// service 是一条路由信息：网关按前缀把请求转发给对应服务。
type service struct {
	name string
	path string
}

// gateway 是流量的唯一入口：先匹配路由，都不命中就返回 404。
type gateway struct {
	routes []service
}

func (g *gateway) handle(path string) string {
	for _, s := range g.routes {
		if path == s.path { // 只匹配完全相等，子路径全都落到 404
			return s.name + " 处理 " + path
		}
	}
	return "404 " + path + " 无匹配路由"
}

func main() {
	g := &gateway{routes: []service{{"订单服务", "/api/orders"}, {"用户服务", "/api/users"}}}
	fmt.Println(g.handle("/api/orders/1001"))
	fmt.Println(g.handle("/api/users/7"))
	fmt.Println(g.handle("/api/pay/1"))
}

