package main

import "fmt"

// orderAPI 用「已处理集合」实现幂等：同一个幂等键只创建一次订单。
type orderAPI struct {
	processed map[string]string // 幂等键 → 首次创建的订单号
	seq       int
}

// create 返回处理结果；重复请求直接返回原订单，不会重复下单。
func (a *orderAPI) create(key string) string {
	if orderID, ok := a.processed[key]; ok {
		return "重复请求 " + key + " 返回已有订单 " + orderID
	}
	a.seq++
	orderID := "order-" + fmt.Sprint(a.seq)
	a.processed[key] = orderID
	return "创建订单 " + orderID + " 幂等键 " + key
}

func main() {
	a := &orderAPI{processed: map[string]string{}}
	fmt.Println(a.create("key-1001"))
	fmt.Println(a.create("key-1001")) // 重试、网络重发带来的重复请求
	fmt.Println(a.create("key-1002"))
}

