package main

import "fmt"

// collect 模拟一个消费者：从自己的队列顺序取事件，收齐后交回结果。
func collect(service string, in <-chan string, done chan<- []string) {
	logs := make([]string, 0, 3)
	for e := range in {
		logs = append(logs, service+" 处理 "+e)
	}
	done <- logs
}

func main() {
	stock, points := make(chan string, 3), make(chan string, 3)
	go func() { // 生产者：每个事件都投递给两个消费者队列
		for _, e := range []string{"OrderCreated 1001", "OrderCreated 1002", "OrderCreated 1003"} {
			stock <- e
			points <- e
		}
		close(stock)
		close(points)
	}()
	stockDone, pointsDone := make(chan []string), make(chan []string)
	go collect("库存服务", stock, stockDone)
	go collect("积分服务", points, pointsDone)
	stockLogs, pointsLogs := <-stockDone, <-pointsDone // 先收齐再打印，输出才确定
	for i := range stockLogs { // 按事件顺序交错输出
		fmt.Println(stockLogs[i])
		fmt.Println(pointsLogs[i])
	}
}

